<template><div class="art-full-height page"><ArtSearchBar v-model="filters" :items="[{label:'手机号',key:'phone',type:'input',props:{placeholder:'请输入手机号，不填查询全部用户流水'}}]" :show-expand="false" @search="load" @reset="reset"/><ElCard class="art-table-card"><ArtTableHeader :loading="loading" @refresh="load"/><ElTable v-loading="loading" :data="rows"><ElTableColumn type="index" label="序号" width="60"/><ElTableColumn prop="customer_id" label="用户ID"/><ElTableColumn prop="type" label="资金类型"/><ElTableColumn prop="direction" label="方向"/><ElTableColumn prop="remark" label="说明" min-width="220"/><ElTableColumn label="变动金额"><template #default="{row}"><span :class="row.amount>=0?'in':'out'">{{row.amount>=0?'+':''}}{{row.amount.toFixed(2)}}</span></template></ElTableColumn><ElTableColumn prop="balance" label="变动后余额"/><ElTableColumn prop="currency" label="币种"/><ElTableColumn prop="created_at" label="创建时间" min-width="170"/></ElTable></ElCard></div></template>
<script setup lang="ts">import{fetchCustomerFundRecords,type CustomerFundRecord}from'@/api/system-manage';defineOptions({name:'UserFunds'});const loading=ref(false),rows=ref<CustomerFundRecord[]>([]),filters=reactive({phone:''});const load=async()=>{loading.value=true;try{rows.value=await fetchCustomerFundRecords(filters.phone)}finally{loading.value=false}};const reset=()=>{filters.phone='';load()};onMounted(load)</script><style scoped>.page{display:flex;flex-direction:column;gap:12px}.art-table-card{flex:1}.in{color:var(--el-color-success)}.out{color:var(--el-color-danger)}</style>